import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])

if n % 2 == 0:
    print(2)
else:
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            print(n // i)
            break
    else:
        print(n)

